// Generated by vibelang from src/mac-permission-preload.ts; the migrate flow writes it again with each batch.
import { ipcRenderer } from "electron";
import { MAC_PERMISSION_HELPER_CHANNEL } from "./ipc/channels.js";
window.addEventListener("DOMContentLoaded", () => {
    const send = (action) => ipcRenderer.send(MAC_PERMISSION_HELPER_CHANNEL, action);
    document.getElementById("app")?.addEventListener("dragstart", (event) => {
        event.preventDefault();
        send("drag");
    });
    document.getElementById("app")?.addEventListener("click", () => send("finder"));
    document.getElementById("close")?.addEventListener("click", () => send("close"));
    document.addEventListener("keydown", (event) => {
        if (event.key === "Escape")
            send("close");
    });
});
